-- generated by scripts/sync-shared.sh - never edit them; edit this file and re-sync.
--[[
    shared/ui/Tabs.lua - Horizontal tab strip.

    Tabs:Create(parent, { tabs = { {key=, label=}, ... }, onSelect = fn(key),
    tabWidth = 90, tabHeight = 24, gap = 2, selected = key })
    Returns an object with :Select(key), :GetSelected() and `.frame` (anchor it).
]]

local _, addon = ...

addon.UI = addon.UI or {}
addon.UI.Tabs = addon.UI.Tabs or {}
local Tabs = addon.UI.Tabs
local PHUI = addon.UI.PHUI

function Tabs:Create(parent, opts)
    local tabWidth = opts.tabWidth or 90
    local tabHeight = opts.tabHeight or 24
    local gap = opts.gap or 2

    local strip = {}
    strip.frame = CreateFrame("Frame", nil, parent)
    strip.frame:SetSize(#opts.tabs * (tabWidth + gap), tabHeight)
    strip.buttons = {}
    strip.selected = nil

    local function paint(button, isSelected)
        local border = isSelected and PHUI.Colors.ACCENT_GOLD or PHUI.Colors.DIVIDER
        local bg = isSelected and PHUI.Colors.SELECTED or PHUI.Colors.BG_DARK
        button:SetBackdropColor(bg[1], bg[2], bg[3], bg[4] or 1)
        button:SetBackdropBorderColor(border[1], border[2], border[3], 1)
        PHUI.ApplyTextStyle(button.label, isSelected and "primary" or "muted")
    end

    for i, tab in ipairs(opts.tabs) do
        local button = CreateFrame("Button", nil, strip.frame, "BackdropTemplate")
        button:SetSize(tabWidth, tabHeight)
        button:SetPoint("TOPLEFT", strip.frame, "TOPLEFT", (i - 1) * (tabWidth + gap), 0)
        button:SetBackdrop(PHUI.Backdrops.ROUNDED_SMALL)
        button.label = PHUI.CreateLabel(button, "muted", tab.label, PHUI.Fonts.NORMAL)
        button.label:SetPoint("CENTER", button, "CENTER", 0, 0)
        button.key = tab.key
        button:SetScript("OnClick", function() strip:Select(tab.key) end)
        strip.buttons[tab.key] = button
        paint(button, false)
    end

    function strip:Select(key)
        if not self.buttons[key] then return end
        self.selected = key
        for k, button in pairs(self.buttons) do paint(button, k == key) end
        if opts.onSelect then opts.onSelect(key) end
    end

    function strip:GetSelected()
        return self.selected
    end

    if opts.selected then strip:Select(opts.selected) end
    return strip
end
